", "content": [{"type": "text", "text": "不要逐字逐句读全文"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "时间分配：读文章2分钟，答题3分钟"}]}]}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#eff6ff", "borderColor": "#3b82f6", "icon": "📊"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "刷题建议：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "篇章阅读是言语理解中最耗时的题型。掌握跳读和定位技巧是关键。"}]}]}]}$$ AS jsonb), NULL, '言语理解-篇章阅读概述的核心知识点和解题方法。', category_node.id, CAST('["言语理解", "篇章阅读概述"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_language_passage_reading", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
